		location.href='https://yscswc.or.kr/nc_client/file/download.jsp?_folder=/'+folder+'/&_file_p='+fileCode+'&_file_l='+fileName;
	}else if(gigwan_code == "5"){
		location.href='https://usswc.or.kr/nc_client/file/download.jsp?_folder=/'+folder+'/&_file_p='+fileCode+'&_file_l='+fileName;
